<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { locale } from '../i18n'
import { createRunRevision, shouldPollRun } from '../utils/runRevision'
import { submitScopedRun, readScopedRun, cancelScopedRun, listScopedRuns } from '../api/scopedMultiagent'
import type { ScopedRun } from '../api/scopedMultiagent'
import { sessionGeneration, sessionState, subscribeSession, SessionRequestError } from '../utils/sessionRequest'
const zh=computed(()=>locale.value==='zh-CN');const tr=(cn:string,en:string)=>zh.value?cn:en
const goal=ref(''), seconds=ref(90), busy=ref(false), issue=ref(''), selected=ref(''), current=ref<ScopedRun|null>(null), runs=ref<ScopedRun[]>([])
let alive=true, timer:ReturnType<typeof setTimeout>|undefined
const revision=createRunRevision()
const report=computed(()=>current.value?.run.report)
const active=computed(()=>!!selected.value&&!['completed','failed','cancelled'].includes(report.value?.status||''))
const tasks=computed(()=>[...(report.value?.planningTask?[{...report.value.planningTask,role:'planner'}]:[]),...(report.value?.tasks||[]).map(task=>({...task,role:'worker'})),...(report.value?.synthesisTask?[{...report.value.synthesisTask,role:'supervisor'}]:[])])
const tools=computed(()=>(current.value?.events||[]).filter(event=>event.data?.event))
const phase=(value?:string)=>({queued:tr('排队中','Queued'),planning:tr('制定计划','Planning'),running:tr('执行任务','Running'),synthesizing:tr('汇总回答','Synthesizing'),completed:tr('已完成','Completed'),failed:tr('执行失败','Failed'),cancelled:tr('已取消','Cancelled')}[value||'']||value||tr('等待状态','Waiting'))
const taskPhase=(value:string)=>({PENDING:tr('等待依赖','Pending'),IN_PROGRESS:tr('执行中','Running'),COMPLETED:tr('已完成','Completed'),FAILED:tr('失败','Failed'),BLOCKED:tr('依赖阻塞','Blocked'),CANCELLED:tr('已取消','Cancelled')}[value]||value)
const toolPhase=(value?:string)=>({TOOL_REQUESTED:tr('请求工具','Requested'),TOOL_STARTED:tr('正在调用','Started'),TOOL_COMPLETED:tr('调用完成','Completed'),TOOL_FAILED:tr('调用失败','Failed')}[value||'']||value)
function clearTimer(){if(timer)clearTimeout(timer);timer=undefined}
function safeError(error:unknown){if(error instanceof SessionRequestError&&error.code==='STALE_SESSION')return;issue.value=error instanceof SessionRequestError?error.code:'REQUEST_FAILED'}
const errorText=computed(()=>({NOT_FOUND:tr('运行不存在或当前账号不可见。','This run is unavailable to your account.'),UNAUTHENTICATED:tr('登录已失效，请重新登录。','Your session expired. Sign in again.'),ACTION_DENIED:tr('当前操作未获允许。','This action is not permitted.'),AUTHORIZATION_INTEGRATION_PENDING:tr('运行服务正在准备，请稍后重试。','The run service is not ready. Try again later.'),DEPENDENCY_UNAVAILABLE:tr('运行依赖暂不可用，请稍后重试。','A run dependency is unavailable. Try again later.')}[issue.value]||tr('请求未完成，请刷新或稍后重试。','The request did not finish. Refresh or try again later.')))
async function refresh(){const version=revision.current();try{const data=await listScopedRuns();if(alive&&revision.isCurrent(version))runs.value=data.runs}catch(error){if(alive&&revision.isCurrent(version))safeError(error)}}
async function load(id:string){clearTimer();const version=revision.next();selected.value=id;current.value=null;issue.value='';await poll(id,version)}
async function poll(id:string,version:number){try{const value=await readScopedRun(id);if(!alive||!revision.isCurrent(version))return;current.value=value;const index=runs.value.findIndex(row=>row.run.executionId===id);if(index<0)runs.value.unshift(value);else runs.value[index]=value;if(shouldPollRun(value.run.report?.status,value.run.runtime.cleanupPending))timer=setTimeout(()=>{void poll(id,version)},1500)}catch(error){if(alive&&revision.isCurrent(version)){safeError(error);current.value=null}}}
async function submit(){if(!goal.value.trim()||busy.value)return;busy.value=true;issue.value='';const generation=sessionGeneration();try{const response=await submitScopedRun(goal.value.trim(),seconds.value*1000);if(alive&&generation===sessionGeneration())await load(response.executionId)}catch(error){safeError(error)}finally{if(alive)busy.value=false}}
async function cancel(){if(!selected.value||busy.value)return;busy.value=true;issue.value='';clearTimer();const id=selected.value,version=revision.next();try{await cancelScopedRun(id);if(alive&&revision.isCurrent(version)){clearTimer();await poll(id,version)}}catch(error){if(alive&&revision.isCurrent(version))safeError(error)}finally{if(alive)busy.value=false}}
let generation=sessionGeneration();const stop=subscribeSession(()=>{if(generation===sessionGeneration())return;generation=sessionGeneration();revision.next();clearTimer();current.value=null;runs.value=[];selected.value='';goal.value='';issue.value='';busy.value=false;if(sessionState().status?.authenticated)void refresh()})
onMounted(()=>{void refresh()});onUnmounted(()=>{alive=false;revision.next();clearTimer();stop()})
</script>
<template>
 <main class="formal-workspace">
  <header><p class="eyebrow">{{ tr('企业协作 · 我的运行','ENTERPRISE WORKSPACE · MY RUNS') }}</p><h1>{{ tr('让多个 Agent 协作完成目标','One goal. A coordinated team.') }}</h1><p>{{ tr('查看计划、真实工具调用与最终结果。运行记录仅对当前账号开放。','Follow the plan, actual tool calls and final result. Run records are private to your account.') }}</p></header>
  <p v-if="issue" class="notice" role="alert">{{ errorText }}</p>
  <div class="workspace-grid">
   <aside><section class="sheet"><h2>{{ tr('开始协作','Start a run') }}</h2><form @submit.prevent="submit"><label for="formal-goal">{{ tr('你希望完成什么？','What would you like to accomplish?') }}</label><textarea id="formal-goal" v-model="goal" rows="6" maxlength="12000" required :placeholder="tr('例如：根据知识库分析 VPN-401，给出有引用的处理建议。','For example: research VPN-401 in the knowledge library and cite the evidence.')"/><label for="formal-budget">{{ tr('执行预算（秒）','Execution budget (seconds)') }}</label><input id="formal-budget" v-model.number="seconds" type="number" min="1" max="180" required/><button class="primary" type="submit" :disabled="busy||!goal.trim()">{{ busy?tr('正在处理…','Working…'):tr('开始执行 →','Start run →') }}</button></form></section>
   <section class="sheet history"><div class="row"><h2>{{ tr('我的运行','My runs') }}</h2><button type="button" @click="refresh">{{ tr('刷新列表','Refresh list') }}</button></div><p v-if="!runs.length" class="muted">{{ tr('暂无可用运行。提交目标后，进度会显示在这里。','No available runs yet. Submit a goal to follow its progress.') }}</p><button v-for="item in runs" :key="item.run.executionId" class="run-item" :class="{selected:selected===item.run.executionId}" type="button" @click="load(item.run.executionId)"><strong>{{ item.run.report?.goal||tr('查看运行','View run') }}</strong><span>{{ phase(item.run.report?.status) }} · {{ item.run.executionId.slice(0,8) }}</span></button></section></aside>
   <section class="sheet run-detail" aria-live="polite"><template v-if="selected"><div class="row"><div><p class="eyebrow">{{ tr('当前运行','CURRENT RUN') }}</p><h2>{{ phase(report?.status) }}</h2></div><div class="actions"><button type="button" @click="load(selected)">{{ tr('刷新运行','Refresh run') }}</button><button v-if="active" type="button" :disabled="busy" @click="cancel">{{ tr('取消运行','Cancel run') }}</button></div></div><code class="run-id">{{ selected }}</code><p v-if="current?.run.runtime.cancelRequested" class="muted">{{ tr('已接收取消请求。','Cancellation accepted.') }}</p><p v-if="current?.run.runtime.cleanupPending" class="muted">{{ tr('运行已结束，仍有调用正在清理。','The run ended; outstanding calls are being cleaned up.') }}</p>
   <ol class="task-list"><li v-for="(task,index) in tasks" :key="task.id||index"><div class="row"><strong>{{ task.description||task.role }}</strong><span>{{ taskPhase(task.status) }}</span></div><small>{{ tr('模型调用','Model calls') }} {{ task.modelCalls||0 }}<template v-if="task.dependencies?.length"> · {{ tr('依赖','Depends on') }} {{ task.dependencies.join(', ') }}</template></small><details v-if="task.result" class="task-output"><summary>{{ task.role==='planner'?tr('查看计划结构','View plan structure'):tr('查看任务输出','View task output') }}</summary><pre>{{ task.result }}</pre></details><p v-if="task.failure" class="muted">{{ task.failure.message||tr('任务未完成','Task did not finish') }}</p></li></ol>
   <section v-if="tools.length" class="tool-section"><h3>{{ tr('真实工具调用','Actual tool calls') }}</h3><details v-for="event in tools" :key="event.id"><summary><span class="tool-dot"></span>{{ event.data?.event?.toolName }} · {{ toolPhase(event.data?.event?.type) }}</summary><p class="muted">{{ event.data?.taskId }}</p><pre>{{ event.data?.event?.arguments }}</pre><pre>{{ event.data?.event?.content }}</pre></details></section>
   <section v-if="report?.result" class="answer"><h3>{{ tr('最终回答','Final answer') }}</h3><p class="prewrap">{{ report.result }}</p></section><p v-if="report?.error" class="notice">{{ report.error.message||tr('运行未完成，请检查依赖或稍后重试。','The run did not finish. Check dependencies or try again later.') }}</p></template>
   <div v-else class="empty"><span>◇</span><h2>{{ tr('从一个清晰目标开始','Start with a clear goal') }}</h2><p>{{ tr('提交目标或选择自己的运行，查看规划、执行、工具和汇总。','Submit a goal or select your own run to inspect planning, execution, tools and synthesis.') }}</p></div></section>
  </div>
 </main>
</template>
<style scoped>
.formal-workspace{max-width:1380px;margin:auto;padding:56px 36px 80px;color:#263b36}.formal-workspace header{max-width:850px;margin-bottom:32px}h1{font-size:clamp(26px,3vw,42px);letter-spacing:-1.3px;line-height:1.25;margin:12px 0 16px}header>p:last-child,.muted{color:#6b7e77;font-size:14px;line-height:1.7}.eyebrow{color:#428b79;font-size:11px;font-weight:700;letter-spacing:1.5px}.workspace-grid{display:grid;grid-template-columns:330px minmax(0,1fr);gap:24px}aside{display:flex;flex-direction:column;gap:20px}.sheet{background:#fffdfa;border:1px solid #dce6df;border-radius:16px;padding:25px;box-shadow:0 6px 30px #35544605}h2{font-size:18px;margin:0 0 18px}h3{font-size:16px}form{display:grid;gap:12px}label{font-size:13px;font-weight:600}textarea,input{box-sizing:border-box;width:100%;border:1px solid #d5e1da;border-radius:9px;background:#fff;padding:12px;font:inherit;color:inherit;resize:vertical}button{cursor:pointer;font:inherit;font-size:12px;border:1px solid #d5e1da;background:#fff;border-radius:8px;padding:9px 12px;color:#395c50}button:disabled{opacity:.5;cursor:wait}.primary{background:#367f6b;color:white;border:0;padding:13px;font-weight:700}.row{display:flex;justify-content:space-between;align-items:center;gap:12px}.row h2{margin:0}.actions{display:flex;gap:8px}.run-id{display:block;font-size:11px;overflow-wrap:anywhere;margin:14px 0 24px;color:#73887e}.history .row{margin-bottom:18px}.run-item{display:grid;text-align:left;gap:6px;width:100%;margin-top:8px;padding:13px}.run-item strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.run-item span{color:#7e8b83;font-size:11px}.run-item.selected{background:#edf5ef;border-color:#78ae99}.run-detail{min-height:460px}.task-list{padding:0;list-style:none;display:grid;gap:12px}.task-list li{border-left:3px solid #80ae98;background:#f5f7f2;padding:16px;border-radius:0 8px 8px 0}.task-list strong{font-size:14px}.task-list span,small{font-size:11px;color:#6b7e77}.task-list small{display:block;margin-top:9px}.prewrap,pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font-size:13px}pre{max-height:260px;overflow:auto;background:#f4f5f0;padding:12px;border-radius:7px}.answer{border-top:1px solid #e3e9df;margin-top:24px;padding-top:14px}.notice{background:#fff0e1;color:#805e36;border:1px solid #ebd8b9;padding:14px 18px;border-radius:9px;line-height:1.6;font-size:13px}.empty{display:grid;place-content:center;text-align:center;min-height:400px;color:#6d8175}.empty>span{font-size:42px;color:#6c9d84}.empty p{max-width:390px;font-size:14px;line-height:1.8}.tool-section details{border-bottom:1px solid #e5e9e1;padding:12px 0;font-size:12px}.tool-dot{display:inline-block;background:#5aaf91;width:6px;height:6px;border-radius:50%;margin-right:8px}summary{cursor:pointer}button:focus-visible,textarea:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid #367f6b;outline-offset:3px}@media(max-width:850px){.workspace-grid{grid-template-columns:1fr}.formal-workspace{padding:32px 18px}.row{flex-wrap:wrap}.sheet{padding:20px}}
</style>
